css:
.loader {
  position: relative;
  width: 52px;
  height: 40px;
  animation: hover 1.4s ease-in-out infinite;
}
.loader::before {
  content: "";
  position: absolute;
  bottom: 8px;
  left: 6px;
  width: 30px;
  height: 16px;
  background: #6366f1;
  border-radius: 12px 8px 8px 12px;
}
.loader::after {
  content: "";
  position: absolute;
  top: 16px;
  left: 34px;
  width: 16px;
  height: 4px;
  background: #6366f1;
  border-radius: 2px;
}
.loader i {
  position: absolute;
  top: 8px;
  left: 19px;
  width: 4px;
  height: 10px;
  background: #4338ca;
}
.loader i::before {
  content: "";
  position: absolute;
  top: -3px;
  left: 50%;
  width: 44px;
  height: 3px;
  margin-left: -22px;
  border-radius: 2px;
  background: #6366f1;
  transform-origin: center;
  animation: spin 0.18s linear infinite;
}
@keyframes hover {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-3px); }
}
@keyframes spin { to { transform: rotate(360deg); } }
